import{_ as t}from"./chunks/knowledge-base.Co7nYv_M.js";import{_ as s,o as a,c as n,ag as r}from"./chunks/framework.DqVSm8kp.js";const g=JSON.parse('{"title":"Base de Connaissances","description":"","frontmatter":{},"headers":[],"relativePath":"fr/guide/knowledge-base.md","filePath":"fr/guide/knowledge-base.md"}'),o={name:"fr/guide/knowledge-base.md"};function i(d,e,l,c,u,m){return a(),n("div",null,[...e[0]||(e[0]=[r('<h1 id="base-de-connaissances" tabindex="-1">Base de Connaissances <a class="header-anchor" href="#base-de-connaissances" aria-label="Permalink to &quot;Base de Connaissances&quot;">​</a></h1><p>La page Base de Connaissances implemente un pipeline RAG (Retrieval-Augmented Generation) complet et local. Televersez vos documents, generez leurs embeddings et recherchez en langage naturel -- le tout stocke dans votre navigateur.</p><p><strong>Element de la barre laterale :</strong> Base de Connaissances <strong>Route :</strong> <code>/rag</code></p><p><img src="'+t+'" alt="Interface Base de Connaissances"></p><h2 id="qu-est-ce-que-le-rag" tabindex="-1">Qu&#39;est-ce que le RAG ? <a class="header-anchor" href="#qu-est-ce-que-le-rag" aria-label="Permalink to &quot;Qu&#39;est-ce que le RAG ?&quot;">​</a></h2><p>RAG signifie <strong>Retrieval-Augmented Generation</strong> (Generation Augmentee par la Recuperation). Au lieu de se fier uniquement a ce sur quoi un modele a ete entraine, le RAG permet de lui fournir des extraits pertinents de vos propres documents. Le modele utilise ensuite ces extraits comme contexte pour donner des reponses plus precises et ancrees dans vos donnees.</p><h2 id="televersement-de-documents" tabindex="-1">Televersement de documents <a class="header-anchor" href="#televersement-de-documents" aria-label="Permalink to &quot;Televersement de documents&quot;">​</a></h2><p>Cliquez sur <strong>Telecharger</strong> et selectionnez un ou plusieurs fichiers. Formats pris en charge :</p><table tabindex="0"><thead><tr><th>Format</th><th>Extension</th><th>Analyseur</th></tr></thead><tbody><tr><td>PDF</td><td><code>.pdf</code></td><td>pdfjs-dist (charge a la demande)</td></tr><tr><td>Word</td><td><code>.docx</code></td><td>mammoth</td></tr><tr><td>Texte brut</td><td><code>.txt</code>, <code>.md</code></td><td>Natif</td></tr><tr><td>CSV</td><td><code>.csv</code></td><td>papaparse</td></tr></tbody></table><h2 id="le-pipeline-d-ingestion" tabindex="-1">Le pipeline d&#39;ingestion <a class="header-anchor" href="#le-pipeline-d-ingestion" aria-label="Permalink to &quot;Le pipeline d&#39;ingestion&quot;">​</a></h2><p>Apres le televersement, chaque document passe par trois etapes :</p><ol><li><strong>Analyse</strong> -- Extraction du texte brut depuis le format de fichier</li><li><strong>Decoupage</strong> -- Fractionnement du texte en segments chevauchants (taille et chevauchement configurables)</li><li><strong>Embedding</strong> -- Generation d&#39;un vecteur pour chaque segment a l&#39;aide du modele d&#39;embedding choisi</li></ol><p>La progression est affichee par document. Une fois termine, le statut du document passe a &quot;Pret&quot;.</p><h2 id="recherche" tabindex="-1">Recherche <a class="header-anchor" href="#recherche" aria-label="Permalink to &quot;Recherche&quot;">​</a></h2><ol><li>Saisissez une requete en langage naturel dans la barre de recherche.</li><li>Les resultats apparaissent classes par <strong>similarite cosinus</strong> -- les segments les plus pertinents semantiquement en premier.</li><li>Chaque resultat affiche : <ul><li>L&#39;extrait de texte correspondant</li><li>Le nom du document source</li><li>Le score de similarite</li><li>Les metadonnees (numero de page, section, positions dans le texte)</li></ul></li></ol><h2 id="gestion-des-documents" tabindex="-1">Gestion des documents <a class="header-anchor" href="#gestion-des-documents" aria-label="Permalink to &quot;Gestion des documents&quot;">​</a></h2><ul><li><strong>Activer/Desactiver</strong> -- Basculez les documents pour la recherche. Les documents desactives ne sont pas inclus dans les resultats.</li><li><strong>Supprimer</strong> -- Supprime un document et tous ses segments d&#39;IndexedDB.</li><li><strong>Indicateurs de statut</strong> -- Affiche l&#39;etape de traitement (analyse, decoupage, embedding, pret, erreur).</li></ul><h2 id="stockage" tabindex="-1">Stockage <a class="header-anchor" href="#stockage" aria-label="Permalink to &quot;Stockage&quot;">​</a></h2><p>Tout est stocke dans <strong>IndexedDB</strong>, la base de donnees integree de votre navigateur :</p><ul><li>Zero cout -- aucun service externe necessaire</li><li>Zero configuration -- fonctionne immediatement</li><li>Les donnees restent sur votre machine</li><li>Survit aux actualisations du navigateur (mais pas a l&#39;effacement des donnees du navigateur)</li></ul><h2 id="integration-avec-le-chat" tabindex="-1">Integration avec le Chat <a class="header-anchor" href="#integration-avec-le-chat" aria-label="Permalink to &quot;Integration avec le Chat&quot;">​</a></h2><p>Lorsque vous avez des documents dans la Base de Connaissances, les segments pertinents peuvent etre automatiquement inclus comme contexte dans vos conversations de chat, ancrant les reponses du modele dans vos donnees.</p><h2 id="astuces" tabindex="-1">Astuces <a class="header-anchor" href="#astuces" aria-label="Permalink to &quot;Astuces&quot;">​</a></h2><ul><li><strong>Des segments plus petits</strong> (200-400 tokens) tendent a produire des resultats de recherche plus precis.</li><li><strong>Le modele d&#39;embedding compte</strong> -- <code>nomic-embed-text</code> fonctionne generalement bien pour les textes en anglais.</li><li>Les PDF volumineux prennent du temps a traiter. L&#39;interface affiche la progression pour que vous puissiez suivre le pipeline.</li><li>Vous pouvez telecharger plusieurs documents et effectuer des recherches sur l&#39;ensemble simultanement.</li></ul>',24)])])}const f=s(o,[["render",i]]);export{g as __pageData,f as default};
